import React, { useEffect, useRef, useState } from 'react';
import { toast } from 'react-toastify';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiStar,
  FiImage,
  FiMessageSquare,
  FiUser,
  FiCheckCircle,
} from 'react-icons/fi';

import api from '../../services/api';
import { getImageUrl } from '../../utils/helpers';

import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';


// ==========================================
// DEFAULT AVATAR
// ==========================================
const DEFAULT_AVATAR = '/default-avatar.png';


// ==========================================
// INITIAL FORM
// ==========================================
const initialForm = {
  name: '',
  role: '',
  content: '',
  rating: 5,
  is_active: true,
  order: 0,
};


// ==========================================
// ADMIN TESTIMONIALS
// ==========================================
const AdminTestimonials = () => {

  // ========================================
  // STATES
  // ========================================
  const [testimonials, setTestimonials] = useState([]);
  const [loading, setLoading] = useState(true);

  const [modalOpen, setModalOpen] = useState(false);

  const [
    editingTestimonial,
    setEditingTestimonial,
  ] = useState(null);

  const [formData, setFormData] =
    useState(initialForm);

  const [avatarFile, setAvatarFile] =
    useState(null);

  const [avatarPreview, setAvatarPreview] =
    useState(null);

  const fileInputRef = useRef(null);


  // ========================================
  // LOAD TESTIMONIALS
  // ========================================
  useEffect(() => {
    fetchTestimonials();
  }, []);


  // ========================================
  // CLEAN PREVIEW ON UNMOUNT
  // ========================================
  useEffect(() => {
    return () => {
      if (avatarPreview) {
        URL.revokeObjectURL(avatarPreview);
      }
    };
  }, [avatarPreview]);


  // ========================================
  // FETCH TESTIMONIALS
  // ========================================
  const fetchTestimonials = async () => {

    try {

      const response = await api.get(
        '/api/testimonials/'
      );

      setTestimonials(
        response.data || []
      );

    } catch (error) {

      console.error(
        'Fetch testimonials error:',
        error
      );

      toast.error(
        'Failed to load testimonials'
      );

    } finally {

      setLoading(false);

    }
  };


  // ========================================
  // RESET FORM
  // ========================================
  const resetForm = () => {

    setEditingTestimonial(null);

    setFormData({
      name: '',
      role: '',
      content: '',
      rating: 5,
      is_active: true,
      order: 0,
    });

    setAvatarFile(null);

    if (avatarPreview) {
      URL.revokeObjectURL(
        avatarPreview
      );
    }

    setAvatarPreview(null);

    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };


  // ========================================
  // OPEN CREATE MODAL
  // ========================================
  const openCreateModal = () => {

    resetForm();

    setModalOpen(true);
  };


  // ========================================
  // CLOSE MODAL
  // ========================================
  const closeModal = () => {

    setModalOpen(false);

    resetForm();
  };


  // ========================================
  // AVATAR CHANGE
  // ========================================
  const handleAvatarChange = (e) => {

    const file =
      e.target.files?.[0];

    if (!file) {
      return;
    }

    if (avatarPreview) {
      URL.revokeObjectURL(
        avatarPreview
      );
    }

    setAvatarFile(file);

    setAvatarPreview(
      URL.createObjectURL(file)
    );
  };


  // ========================================
  // SUBMIT CREATE / UPDATE
  // ========================================
  const handleSubmit = async (e) => {

    e.preventDefault();

    try {

      const data = new FormData();

      data.append(
        'name',
        formData.name
      );

      data.append(
        'role',
        formData.role || ''
      );

      data.append(
        'content',
        formData.content
      );

      data.append(
        'rating',
        String(formData.rating)
      );

      data.append(
        'is_active',
        String(formData.is_active)
      );

      data.append(
        'order',
        String(formData.order)
      );


      // ====================================
      // AVATAR
      // ====================================
      if (avatarFile) {

        data.append(
          'avatar',
          avatarFile
        );

      }


      // ====================================
      // UPDATE
      // ====================================
      if (editingTestimonial) {

        await api.put(
          `/api/testimonials/${editingTestimonial.id}`,
          data,
          {
            headers: {
              'Content-Type':
                'multipart/form-data',
            },
          }
        );

        toast.success(
          'Testimonial updated successfully'
        );

      }

      // ====================================
      // CREATE
      // ====================================
      else {

        await api.post(
          '/api/testimonials/',
          data,
          {
            headers: {
              'Content-Type':
                'multipart/form-data',
            },
          }
        );

        toast.success(
          'Testimonial created successfully'
        );

      }


      setModalOpen(false);

      resetForm();

      fetchTestimonials();

    } catch (error) {

      console.error(
        'Testimonial submit error:',
        error
      );

      const detail =
        error.response?.data?.detail ||
        error.response?.data?.message ||
        'Operation failed';

      toast.error(detail);
    }
  };


  // ========================================
  // DELETE
  // ========================================
  const handleDelete = async (id) => {

    const confirmDelete =
      window.confirm(
        'Are you sure you want to delete this testimonial?'
      );

    if (!confirmDelete) {
      return;
    }

    try {

      await api.delete(
        `/api/testimonials/${id}`
      );

      toast.success(
        'Testimonial deleted successfully'
      );

      fetchTestimonials();

    } catch (error) {

      console.error(
        'Delete testimonial error:',
        error
      );

      toast.error(
        error.response?.data?.detail ||
          'Failed to delete testimonial'
      );
    }
  };


  // ========================================
  // EDIT
  // ========================================
  const handleEdit = (testimonial) => {

    setEditingTestimonial(
      testimonial
    );

    setFormData({
      name:
        testimonial.name || '',

      role:
        testimonial.role || '',

      content:
        testimonial.content || '',

      rating:
        testimonial.rating || 5,

      is_active:
        testimonial.is_active ?? true,

      order:
        testimonial.order || 0,
    });

    setAvatarFile(null);

    if (avatarPreview) {

      URL.revokeObjectURL(
        avatarPreview
      );

    }

    setAvatarPreview(null);

    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }

    setModalOpen(true);
  };


  // ========================================
  // RENDER STARS
  // ========================================
  const renderStars = (rating) => {

    const safeRating =
      Math.max(
        0,
        Math.min(
          5,
          Number(rating) || 0
        )
      );

    return (

      <div
        className="
          flex
          items-center
          gap-1
        "
      >

        {[...Array(5)].map(
          (_, index) => (

            <FiStar
              key={index}
              size={16}
              className={
                index < safeRating
                  ? `
                    text-yellow-400
                    fill-current
                  `
                  : 'text-gray-300'
              }
            />

          )
        )}

      </div>
    );
  };


  // ========================================
  // TABLE COLUMNS
  // ========================================
  const columns = [

    // ======================================
    // AVATAR
    // ======================================
    {
      key: 'avatar',
      label: 'Avatar',

      render: (val) => (

        <div
          className="
            w-14
            h-14

            rounded-xl

            overflow-hidden

            border
            border-gray-200

            bg-gray-100

            shadow-sm
          "
        >

          <img
            src={getImageUrl(
              val,
              DEFAULT_AVATAR
            )}
            alt="testimonial"
            className="
              w-full
              h-full
              object-cover
            "
            onError={(e) => {
              e.currentTarget.src =
                DEFAULT_AVATAR;
            }}
          />

        </div>
      ),
    },


    // ======================================
    // NAME
    // ======================================
    {
      key: 'name',
      label: 'Name',

      render: (val) => (

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-blue-50
              text-blue-900

              flex-shrink-0
            "
          >
            <FiUser size={17} />
          </div>


          <p
            className="
              font-semibold
              text-gray-800
            "
          >
            {val || '-'}
          </p>

        </div>
      ),
    },


    // ======================================
    // ROLE
    // ======================================
    {
      key: 'role',
      label: 'Role',

      render: (val) => (

        <span
          className="
            inline-flex

            px-3
            py-1.5

            rounded-full

            bg-blue-50
            text-blue-800

            border
            border-blue-100

            text-xs
            font-medium
          "
        >
          {val || '-'}
        </span>
      ),
    },


    // ======================================
    // CONTENT
    // ======================================
    {
      key: 'content',
      label: 'Content',

      render: (val) => (

        <p
          className="
            max-w-xs

            text-sm
            text-gray-600

            line-clamp-2

            leading-5
          "
        >
          {val || '-'}
        </p>
      ),
    },


    // ======================================
    // RATING
    // ======================================
    {
      key: 'rating',
      label: 'Rating',

      render: (val) => (

        <div className="space-y-1">

          {renderStars(val)}

          <span
            className="
              text-xs
              text-gray-400
            "
          >
            {val || 0}/5
          </span>

        </div>
      ),
    },


    // ======================================
    // STATUS
    // ======================================
    {
      key: 'is_active',
      label: 'Status',

      render: (val) => (

        <span
          className={`
            inline-flex
            items-center
            gap-2

            px-3
            py-1.5

            rounded-full

            text-xs
            font-semibold

            border

            ${
              val
                ? `
                  bg-green-50
                  text-green-700
                  border-green-200
                `
                : `
                  bg-red-50
                  text-red-700
                  border-red-200
                `
            }
          `}
        >

          <span
            className={`
              w-2
              h-2
              rounded-full

              ${
                val
                  ? 'bg-green-500'
                  : 'bg-red-500'
              }
            `}
          />

          {val
            ? 'Active'
            : 'Inactive'}

        </span>
      ),
    },


    // ======================================
    // ACTIONS
    // ======================================
    {
      key: 'actions',
      label: 'Actions',

      render: (_, row) => (

        <div
          className="
            flex
            items-center
            gap-2
          "
        >

          <button
            type="button"
            onClick={() =>
              handleEdit(row)
            }
            title="Edit Testimonial"
            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-blue-50
              text-blue-600

              hover:bg-blue-600
              hover:text-white

              transition-all
              duration-200
            "
          >
            <FiEdit2 size={16} />
          </button>


          <button
            type="button"
            onClick={() =>
              handleDelete(row.id)
            }
            title="Delete Testimonial"
            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-red-50
              text-red-600

              hover:bg-red-600
              hover:text-white

              transition-all
              duration-200
            "
          >
            <FiTrash2 size={16} />
          </button>

        </div>
      ),
    },
  ];


  // ========================================
  // RETURN
  // ========================================
  return (

    <div className="w-full">

      {/* ====================================
          PAGE HEADER
      ==================================== */}
      <div
        className="
          flex
          flex-col
          sm:flex-row

          sm:items-center
          sm:justify-between

          gap-4

          mb-7
        "
      >

        {/* LEFT */}
        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          {/* ICON */}
          <div
            className="
              w-12
              h-12

              flex
              items-center
              justify-center

              rounded-xl

              bg-blue-900
              text-white

              shadow-sm
            "
          >
            <FiMessageSquare size={22} />
          </div>


          {/* TITLE */}
          <div>

            <h1
              className="
                text-2xl
                md:text-3xl

                font-bold

                text-blue-950

                leading-tight
              "
            >
              Testimonials Management
            </h1>

            <p
              className="
                text-sm
                text-gray-500
                mt-1
              "
            >
              Manage testimonials,
              ratings and customer feedback
            </p>

          </div>

        </div>


        {/* ADD BUTTON */}
        <button
          type="button"
          onClick={openCreateModal}
          className="
            inline-flex
            items-center
            justify-center
            gap-2

            h-11

            px-5

            bg-blue-900
            hover:bg-blue-950

            text-white

            rounded-xl

            text-sm
            font-semibold

            shadow-sm
            hover:shadow-md

            transition-all
            duration-200
          "
        >
          <FiPlus size={18} />

          Add Testimonial
        </button>

      </div>


      {/* ====================================
          TABLE CARD
      ==================================== */}
      <AdminCard
        className="
          overflow-hidden

          bg-white

          border
          border-gray-100

          rounded-2xl

          shadow-sm
        "
      >

        <AdminTable
          columns={columns}
          data={testimonials}
          loading={loading}
        />

      </AdminCard>


      {/* ====================================
          MODAL
      ==================================== */}
      <AdminModal
        isOpen={modalOpen}
        onClose={closeModal}
        title={
          editingTestimonial
            ? 'Edit Testimonial'
            : 'Create Testimonial'
        }
      >

        <form onSubmit={handleSubmit}>

          <div className="space-y-5">

            {/* =================================
                NAME + ROLE
            ================================= */}
            <div
              className="
                grid
                grid-cols-1
                md:grid-cols-2
                gap-4
              "
            >

              {/* NAME */}
              <div>

                <label className="admin-label">
                  Name

                  <span
                    className="
                      text-red-500
                      ml-1
                    "
                  >
                    *
                  </span>
                </label>

                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      name:
                        e.target.value,
                    })
                  }
                  className="
                    admin-input

                    rounded-xl

                    border-gray-300

                    focus:border-blue-500
                    focus:ring-blue-500
                  "
                  placeholder="Enter person's name"
                  required
                />

              </div>


              {/* ROLE */}
              <div>

                <label className="admin-label">
                  Role
                </label>

                <input
                  type="text"
                  value={formData.role}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      role:
                        e.target.value,
                    })
                  }
                  className="
                    admin-input

                    rounded-xl

                    border-gray-300

                    focus:border-blue-500
                    focus:ring-blue-500
                  "
                  placeholder="Student, English Program"
                />

              </div>

            </div>


            {/* =================================
                CONTENT
            ================================= */}
            <div>

              <label className="admin-label">
                Testimonial Content

                <span
                  className="
                    text-red-500
                    ml-1
                  "
                >
                  *
                </span>
              </label>

              <textarea
                value={formData.content}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    content:
                      e.target.value,
                  })
                }
                className="
                  admin-input

                  rounded-xl

                  border-gray-300

                  focus:border-blue-500
                  focus:ring-blue-500

                  resize-none
                "
                rows="4"
                placeholder="Write the testimonial..."
                required
              />

            </div>


            {/* =================================
                RATING + ORDER
            ================================= */}
            <div
              className="
                grid
                grid-cols-1
                md:grid-cols-2
                gap-4
              "
            >

              {/* RATING */}
              <div>

                <label className="admin-label">
                  Rating
                </label>

                <input
                  type="number"
                  min="1"
                  max="5"
                  value={
                    formData.rating
                  }
                  onChange={(e) =>
                    setFormData({
                      ...formData,

                      rating:
                        parseInt(
                          e.target.value
                        ) || 5,
                    })
                  }
                  className="
                    admin-input

                    rounded-xl

                    border-gray-300

                    focus:border-blue-500
                    focus:ring-blue-500
                  "
                />

                <div className="mt-2">
                  {renderStars(
                    formData.rating
                  )}
                </div>

              </div>


              {/* ORDER */}
              <div>

                <label className="admin-label">
                  Display Order
                </label>

                <input
                  type="number"
                  min="0"
                  value={formData.order}
                  onChange={(e) =>
                    setFormData({
                      ...formData,

                      order:
                        parseInt(
                          e.target.value
                        ) || 0,
                    })
                  }
                  className="
                    admin-input

                    rounded-xl

                    border-gray-300

                    focus:border-blue-500
                    focus:ring-blue-500
                  "
                />

              </div>

            </div>


            {/* =================================
                AVATAR UPLOAD
            ================================= */}
            <div>

              <label className="admin-label">
                Avatar Image
              </label>


              <div
                onClick={() =>
                  fileInputRef.current?.click()
                }
                className="
                  group

                  border-2
                  border-dashed
                  border-gray-300

                  hover:border-blue-500

                  bg-gray-50
                  hover:bg-blue-50/40

                  rounded-2xl

                  px-5
                  py-7

                  text-center

                  cursor-pointer

                  transition-all
                  duration-200
                "
              >

                <input
                  ref={fileInputRef}
                  type="file"
                  accept="
                    image/jpeg,
                    image/png,
                    image/webp
                  "
                  onChange={
                    handleAvatarChange
                  }
                  className="hidden"
                />


                {avatarFile ? (

                  <div>

                    <div
                      className="
                        w-14
                        h-14

                        mx-auto
                        mb-3

                        flex
                        items-center
                        justify-center

                        rounded-xl

                        bg-blue-100
                        text-blue-700
                      "
                    >
                      <FiImage size={25} />
                    </div>


                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900

                        break-all
                      "
                    >
                      {avatarFile.name}
                    </p>


                    <p
                      className="
                        text-xs
                        text-gray-400
                        mt-1
                      "
                    >
                      Click to choose
                      another image
                    </p>

                  </div>

                ) : (

                  <div>

                    <div
                      className="
                        w-14
                        h-14

                        mx-auto
                        mb-3

                        flex
                        items-center
                        justify-center

                        rounded-xl

                        bg-white

                        border
                        border-gray-200

                        shadow-sm

                        text-gray-500

                        group-hover:text-blue-600
                        group-hover:scale-105

                        transition-all
                      "
                    >
                      <FiImage size={25} />
                    </div>


                    <p
                      className="
                        text-sm
                        font-semibold
                        text-gray-700
                      "
                    >
                      Click to upload
                      avatar image
                    </p>


                    <p
                      className="
                        text-xs
                        text-gray-400
                        mt-1
                      "
                    >
                      JPG, PNG or WEBP
                    </p>


                    {editingTestimonial &&
                      editingTestimonial.avatar && (

                        <div
                          className="
                            mt-3

                            inline-flex
                            items-center
                            gap-1.5

                            px-3
                            py-1.5

                            rounded-full

                            bg-blue-50
                            text-blue-700

                            text-xs
                            font-medium
                          "
                        >
                          <FiCheckCircle />

                          Current avatar will
                          be kept
                        </div>

                      )}

                  </div>

                )}

              </div>


              {/* AVATAR PREVIEW */}
              {(avatarPreview ||
                (
                  editingTestimonial &&
                  editingTestimonial.avatar
                )) && (

                <div
                  className="
                    mt-4

                    flex
                    justify-center
                  "
                >

                  <div className="relative">

                    <img
                      src={
                        avatarPreview ||
                        getImageUrl(
                          editingTestimonial.avatar,
                          DEFAULT_AVATAR
                        )
                      }
                      alt="Avatar preview"
                      className="
                        w-24
                        h-24

                        rounded-2xl

                        object-cover

                        border-2
                        border-gray-200

                        shadow-sm
                      "
                      onError={(e) => {
                        e.currentTarget.src =
                          DEFAULT_AVATAR;
                      }}
                    />


                    {avatarPreview && (

                      <span
                        className="
                          absolute

                          -bottom-2
                          left-1/2
                          -translate-x-1/2

                          px-2.5
                          py-1

                          rounded-full

                          bg-green-500
                          text-white

                          text-[10px]
                          font-bold

                          shadow-sm
                        "
                      >
                        NEW
                      </span>

                    )}

                  </div>

                </div>

              )}

            </div>


            {/* =================================
                STATUS
            ================================= */}
            <div
              className="
                flex
                items-center
                justify-between

                px-4
                py-3.5

                rounded-xl

                bg-gray-50

                border
                border-gray-200
              "
            >

              <div>

                <p
                  className="
                    text-sm
                    font-semibold
                    text-gray-800
                  "
                >
                  Testimonial Status
                </p>

                <p
                  className="
                    text-xs
                    text-gray-500
                    mt-0.5
                  "
                >
                  Show this testimonial
                  on the website
                </p>

              </div>


              {/* SWITCH */}
              <label
                className="
                  relative
                  inline-flex
                  items-center
                  cursor-pointer
                "
              >

                <input
                  type="checkbox"
                  checked={
                    formData.is_active
                  }
                  onChange={(e) =>
                    setFormData({
                      ...formData,

                      is_active:
                        e.target.checked,
                    })
                  }
                  className="sr-only peer"
                />


                <div
                  className="
                    relative

                    w-11
                    h-6

                    bg-gray-300

                    rounded-full

                    transition-colors

                    peer-checked:bg-blue-900

                    after:content-['']

                    after:absolute
                    after:top-[2px]
                    after:left-[2px]

                    after:w-5
                    after:h-5

                    after:bg-white

                    after:rounded-full

                    after:shadow-sm

                    after:transition-all

                    peer-checked:after:translate-x-full
                  "
                />

              </label>

            </div>

          </div>


          {/* =================================
              FOOTER BUTTONS
          ================================= */}
          <div
            className="
              mt-7
              pt-5

              border-t
              border-gray-100

              flex
              items-center
              justify-end

              gap-3
            "
          >

            <button
              type="button"
              onClick={closeModal}
              className="
                h-11

                px-5

                rounded-xl

                border
                border-gray-300

                bg-white

                text-gray-700

                text-sm
                font-semibold

                hover:bg-gray-50

                transition-all
                duration-200
              "
            >
              Cancel
            </button>


            <button
              type="submit"
              className="
                h-11

                inline-flex
                items-center
                justify-center
                gap-2

                px-6

                rounded-xl

                bg-blue-900
                hover:bg-blue-950

                text-white

                text-sm
                font-semibold

                shadow-sm
                hover:shadow-md

                transition-all
                duration-200
              "
            >

              {editingTestimonial ? (
                <>
                  <FiEdit2 size={16} />
                  Update Testimonial
                </>
              ) : (
                <>
                  <FiPlus size={17} />
                  Create Testimonial
                </>
              )}

            </button>

          </div>

        </form>

      </AdminModal>

    </div>
  );
};


export default AdminTestimonials;
